INSERT INTO _migration_494_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_igbio_genetics_s2_001', 'topic_igcse_bio_genetics', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which statement correctly defines a gene?', 'multiple_choice', NULL, '["A. A length of DNA that codes for a specific protein","B. A whole chromosome found in the nucleus","C. A protein that carries oxygen in the blood","D. A type of cell found in the gametes"]', 'A', 'A gene is a section of a DNA molecule whose base sequence codes for the amino acid sequence of a particular protein. A chromosome carries many genes, an oxygen-carrying protein such as haemoglobin is the product of a gene rather than the gene itself, and genes are lengths of DNA, not cells. Therefore the correct answer is A: A length of DNA that codes for a specific protein.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_genetics_s2_002', 'topic_igcse_bio_genetics', 'subj_igcse_biology', 'igcse', NULL, NULL, 'How many chromosomes are there in a normal human sperm cell?', 'multiple_choice', NULL, '["A. 46","B. 23","C. 22","D. 44"]', 'B', 'Gametes are produced by meiosis and contain half the diploid number — one set of 23 chromosomes — so that the diploid number of 46 is restored at fertilisation. 46 is the number in a body cell, 22 counts only the autosomes and omits the sex chromosome, and 44 is double the autosome number. Therefore the correct answer is B: 23.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_genetics_s2_003', 'topic_igcse_bio_genetics', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Two heterozygous tall pea plants (Tt) are crossed. What is the expected ratio of tall to short plants in the offspring?', 'multiple_choice', NULL, '["A. 1 tall : 1 short","B. All tall","C. 3 tall : 1 short","D. 1 tall : 2 heterozygous : 1 short"]', 'C', 'The cross Tt × Tt gives genotypes 1 TT : 2 Tt : 1 tt, and the TT and Tt plants are all tall because T is dominant, so the phenotype ratio is 3 tall to 1 short. The 1 : 1 ratio comes from a Tt × tt test cross, all tall offspring would require at least one TT parent, and 1 : 2 : 1 is the genotype ratio rather than the phenotype ratio. Therefore the correct answer is C: 3 tall : 1 short.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_igbio_genetics_s2_004', 'topic_igcse_bio_genetics', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which factors are known to increase the rate of mutation?', 'multiple_choice', NULL, '["A. Antibiotics and vaccines","B. A balanced diet and regular exercise","C. High altitude and low humidity","D. Ionising radiation and certain chemicals"]', 'D', 'Ionising radiation such as X-rays and ultraviolet light, together with certain chemicals called mutagens, damage DNA and increase the rate of mutation. Antibiotics and vaccines act on pathogens and the immune system rather than on DNA, diet and exercise affect the phenotype without altering base sequences, and altitude and humidity have no known mutagenic effect. Therefore the correct answer is D: Ionising radiation and certain chemicals.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Recall', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_genetics_s2_005', 'topic_igcse_bio_genetics', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which statement about a dominant allele is correct?', 'multiple_choice', NULL, '["A. It is expressed in the phenotype when only one copy is present","B. It is always the most common allele in a population","C. It must be inherited from both parents to have an effect","D. It is carried only on the X chromosome"]', 'A', 'A dominant allele shows its effect in a heterozygote, so only one copy is needed for the trait to appear in the phenotype. Dominance concerns expression rather than frequency, so a dominant allele can be rare, one copy is sufficient rather than two, and dominant alleles occur on every chromosome, not only the X chromosome. Therefore the correct answer is A: It is expressed in the phenotype when only one copy is present.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_igbio_genetics_s2_006', 'topic_igcse_bio_genetics', 'subj_igcse_biology', 'igcse', NULL, NULL, 'Which human characteristic shows continuous variation?', 'multiple_choice', NULL, '["A. Blood group","B. Height","C. Ability to roll the tongue","D. Sex"]', 'B', 'Height can take any value within a range and is influenced by many genes together with environmental factors such as diet, so it shows continuous variation. Blood group, tongue-rolling ability and sex each fall into distinct categories with no intermediates, which is discontinuous variation. Therefore the correct answer is B: Height.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge');
INSERT INTO _migration_494_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_494_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_494_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_494_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'igcse-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/', 0, 1 FROM _migration_494_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_494_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_494_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 6 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_494_expected e ON e.id = r.question_id WHERE r.batch_id IS 'igcse-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge IGCSE Biology (0610) syllabus; not official Cambridge International, WAEC or NSMQ examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-igcse-biology-0610/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 6 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_494_expected e ON e.id = q.id) = 6 THEN 1 ELSE 0 END;
